/**
  * @param {params} params
  * @param {api} params.api
  * @param {any} params.imports
  */
function evaluateProperty({api}) {
  const events = api.data.fetch_topics.output ? api.data.fetch_topics.output : [];
  return events.map(topic => ({
    id: topic,
    label: topic
  }));
}
